import re, os, sys

PULL_RE = re.compile(r'\bpskb_may_pull(?:_reason)?\s*\(|\bpskb_pull\s*\(|\b__pskb_pull(?:_tail)?\s*\(')

# RHS patterns that derive a pointer into skb data
DERIVE_RE = re.compile(
    r'skb_header_pointer\s*\(|'
    r'skb->data|'
    r'skb->[a-z_]*header|'
    r'\bip_hdr\s*\(|\bipv6_hdr\s*\(|\btcp_hdr\s*\(|\budp_hdr\s*\(|'
    r'\bicmp_hdr\s*\(|\bthdr\s*\(|'
    r'skb_network_header\s*\(|skb_transport_header\s*\(|skb_mac_header\s*\(|'
    r'skb_pull_data\s*\(|'
    r'skb_shinfo\s*\('  # not data but shared info; separate
)

def split_functions(lines):
    funcs = []
    cur_start = None
    depth = 0
    fname = None
    for i, line in enumerate(lines):
        if depth == 0:
            m = re.search(r'^[A-Za-z_][A-Za-z0-9_ \*\t]*\b([A-Za-z_][A-Za-z0-9_]*)\s*\(', line)
            if m and not line.strip().startswith(('#', '//')) and not re.match(r'^(if|for|while|switch|return|else)\b', line.strip()):
                # candidate function start line
                if '{' in line:
                    cur_start = i
                    fname = m.group(1)
                    depth = line.count('{') - line.count('}')
        else:
            depth += line.count('{') - line.count('}')
            if depth <= 0:
                if cur_start is not None:
                    funcs.append((fname, cur_start, i))
                cur_start = None
                depth = 0
                fname = None
    return funcs

def analyze(path):
    with open(path, errors='replace') as f:
        src = f.read()
    lines = src.split('\n')
    results = []
    for fname, s, e in split_functions(lines):
        body_lines = lines[s:e+1]
        body = '\n'.join(body_lines)
        if not PULL_RE.search(body):
            continue
        # find local pointer vars assigned from data-derived RHS
        assign_re = re.compile(r'^\s*(?:const\s+)?(?:struct\s+)?[A-Za-z_][A-Za-z0-9_]*\s*\*\s*([A-Za-z_][A-Za-z0-9_]*)\s*=\s*([^;]+);')
        var_assign = {}  # var -> (line_idx, rhs)
        for idx, ln in enumerate(body_lines):
            m = assign_re.match(ln)
            if m:
                var, rhs = m.group(1), m.group(2)
                if DERIVE_RE.search(rhs) and 'skb' in rhs:
                    var_assign[var] = (idx, rhs.strip())
        if not var_assign:
            continue
        # find pull lines
        pull_idx = [i for i, ln in enumerate(body_lines) if PULL_RE.search(ln)]
        for var, (ai, rhs) in var_assign.items():
            for pi in pull_idx:
                if ai >= pi:
                    continue
                # check usage after pull (allowing same-line: ai<pi strictly)
                use_re = re.compile(r'\b' + re.escape(var) + r'\b')
                after = '\n'.join(body_lines[pi+1:])
                before_pull_assign_after = None
                # skip if var reassigned between assign and pull (i.e., rebased)
                between = '\n'.join(body_lines[ai+1:pi])
                reassigned = re.search(r'\b' + re.escape(var) + r'\s*=[^=]', between)
                if reassigned:
                    continue
                if use_re.search(after):
                    results.append((path, fname, s+ai+1, s+pi+1, var, rhs))
                    break
    return results

allres = []
for root, dirs, files in os.walk('.'):
    if any(x in root for x in ('/tools', '/Documentation', '/samples', '/usr')):
