import re, os, sys

PULL_RE = re.compile(r'\bpskb_may_pull(?:_reason)?\s*\(|\bpskb_pull\s*\(|\b__pskb_pull(?:_tail)?\s*\(')

DERIVE_RE = re.compile(
    r'skb_header_pointer\s*\(|'
    r'\bskb->[a-z_]*data|'
    r'skb->[a-z_]*header|'
    r'\b(ipv6|ip|tcp|udp|icmp|sctp|ah|esp|gre|arp|dccp|geneve|vxlan|mpls)_hdr\s*\(|'
    r'skb_(network|transport|mac|inner_network|inner_transport|inner_mac)_header\s*\(|'
    r'skb_pull_data\s*\(|'
    r'skb_frag_address\s*\(|'
    r'\bvlan_eth_hdr\s*\(|\bPayload\s*\(|'
    r'->data\b'   # e.g. x->data where x is skb-like? too broad but with skb name filter
)

def function_spans(lines):
    """Return list of (name, start_idx, end_idx) using '{' at col 0 as body start."""
    spans = []
    n = len(lines)
    for i, ln in enumerate(lines):
        if ln.startswith('{'):
            # find header above
            j = i - 1
            hdr = []
            while j >= 0:
                s = lines[j].strip()
                if s == '' or s.startswith('*') or s.startswith('/*') or s.startswith('//') or s.endswith('*/'):
                    j -= 1; continue
                hdr.insert(0, lines[j])
                if '(' in lines[j]:
                    break
                j -= 1
            m = re.search(r'([A-Za-z_][A-Za-z0-9_]*)\s*\(', hdr[0]) if hdr else None
            name = m.group(1) if m else '?'
            # find closing '}' at col 0
            k = i
            while k < n and not lines[k].startswith('}'):
                k += 1
            spans.append((name, i, k))
    return spans

def analyze(path):
    with open(path, errors='replace') as f:
        lines = f.read().split('\n')
    results = []
    for fname, s, e in function_spans(lines):
        if e - s < 2:
            continue
        body = lines[s:e+1]
        joined = '\n'.join(body)
        if not PULL_RE.search(joined) or 'skb' not in joined:
            continue
        assign_re = re.compile(r'(?<![=!<>+\-*/&|])\b([A-Za-z_][A-Za-z0-9_]*)\s*=\s*([^;]+?)(?=;)')
        var_assigns = []
        for idx, ln in enumerate(body):
            for m in assign_re.finditer(ln):
                var, rhs = m.group(1), m.group(2)
                if var in ('if','while','for','switch','return'):
                    continue
                if DERIVE_RE.search(rhs):
                    var_assigns.append((idx, var, rhs.strip()))
        if not var_assigns:
            continue
        pull_idx = [i for i, ln in enumerate(body) if PULL_RE.search(ln)]
        for ai, var, rhs in var_assigns:
            for pi in pull_idx:
                if ai >= pi:
                    continue
                between = '\n'.join(body[ai+1:pi])
                if re.search(r'\b'+re.escape(var)+r'\s*=[^=]', between):
                    continue
                after = '\n'.join(body[pi+1:])
                if re.search(r'\b'+re.escape(var)+r'\b', after):
                    results.append((path, fname, s+ai+1, s+pi+1, var, rhs[:70]))
                    break
    return results

allres = []
for root, dirs, files in os.walk('.'):
    dirs[:] = [d for d in dirs if d not in ('tools','Documentation','samples','usr','rust')]
    for fn in files:
        if fn.endswith('.c'):
            p = os.path.join(root, fn)
            try:
