            except Exception as ex:
                print('ERR', p, ex, file=sys.stderr)

for r in allres:
    print('%s:%d | fn=%s | var=%s = %s | pull@%d' % (r[0], r[2], r[1], r[4], r[5], r[3]))
print('TOTAL', len(allres))
